const allIdeas = $input.all();

// Aggregate all ideas into a single report
let report = "**Daily MOEX Trading Report**\n\n";

allIdeas.forEach((item, index) => {
    const idea = item.json;
    report += `**${index + 1}. ${idea.ticker}** (${idea.direction})\n`;
    report += `   Prob: ${idea.probability} | R/R: ${idea.risk_reward_ratio} | Conf: ${idea.confidence_level}\n`;
    report += `   Entry: ${idea.entry_point} | Target: ${idea.target} | SL: ${idea.stop_loss}\n`;
    report += `   Justification: ${idea.justification.technical_setup}\n\n`;
});

return [{ json: { report: report } }];
